// Keep modification notices reproducible without hand-editing generated files.
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const targets = {
  sqlc: ['backend/internal/storage/sqlite/gen/models.go', '// Code generated by sqlc. DO NOT EDIT.'],
  api: ['frontend/src/api/schema.ts', ' * This file was auto-generated by openapi-typescript.'],
};
const target = targets[process.argv[2]];
if (!target || process.argv.length !== 3) {
  throw new Error('Usage: node scripts/swarm/mark-generated.mjs sqlc|api');
}
const [relative, marker] = target;
const path = fileURLToPath(new URL(`../../${relative}`, import.meta.url));
const source = readFileSync(path, 'utf8');
if (!source.includes(marker)) throw new Error(`Unexpected generator header: ${relative}`);
const notice = 'Modified for Praxis Swarm: generated from the fork\'s extended contracts.';
const line = process.argv[2] === 'sqlc' ? `// ${notice}` : ` * ${notice}`;
if (!source.includes(line)) writeFileSync(path, source.replace(marker, `${marker}\n${line}`));
